import { EmailMessage } from "cloudflare:email";
export interface Env { DB: D1Database; ALIAS_CACHE: KVNamespace; PUBLIC_ORIGIN: string; ONE_DB_API_TOKEN?: string; ADMIN_PASSWORD?: string; WAITLIST_EMAIL?: { send(message: EmailMessage): Promise<void> }; }
type Alias={id:string;public_code:string;namespace:string;slug:string;canonical_short_url:string;target_url:string;target_type?:string|null;mode:string;redirect_status_code:number;preserve_query_string:number;append_query_string?:string|null;utm_config?:string|null;is_active:number;expires_utc?:string|null;max_views?:number|null;view_count:number;success_count:number;metadata:string;api_tenant_id?:string|null;tags?:string;notes?:string|null};
type Policy={allowed_origins?:string|null;allowed_referrers?:string|null;allowed_countries?:string|null;denied_countries?:string|null;allowed_methods?:string|null;block_bots:number;block_likely_bots_for_post:number;one_time_use:number};
type Tenant={id:string;slug:string;name:string;allowed_origins:string;rate_limit_per_minute:number;usage_limit_monthly:number;billing_tier:string;is_active:number};
type Auth={tenant:Tenant;keyId:string;scopes:string[]};
const NS=new Set(['a','v','f','c','p','s']); const LINK_SCOPES=['links:create','links:read','links:update','links:delete','routes:create','routes:read','routes:update','routes:delete','intakes:create','intakes:read','analytics:read','cognition:write','cognition:read','admin'];
const now=()=>new Date().toISOString(); const id=(p='id')=>`${p}_${crypto.randomUUID().replaceAll('-','')}`;
const parseJson=<T>(s:string|null|undefined,d:T):T=>{try{return s?JSON.parse(s):d}catch{return d}};
async function sha(s:string){const b=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(s));return [...new Uint8Array(b)].map(x=>x.toString(16).padStart(2,'0')).join('')}
const ok=(data:unknown,status=200,headers:HeadersInit={})=>new Response(JSON.stringify({data},null,2),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store',...headers}});
const rawjson=(data:unknown,status=200)=>new Response(JSON.stringify(data,null,2),{status,headers:{'content-type':'application/json; charset=utf-8','cache-control':'no-store'}});
const err=(code:string,message:string,status=400,requestId=id('req'))=>rawjson({error:{code,message,requestId}},status);
const html=(x:string,s=200,h:HeadersInit={})=>new Response(x,{status:s,headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store',...h}});
function clean(s:string){return (s||'').toLowerCase().replace(/[^a-z0-9_-]/g,'').slice(0,64)} function host(v:string|null|undefined){try{return v?new URL(v).host:''}catch{return ''}}
function arr(s:string|null|undefined){return parseJson<string[]>(s||'',[])} function isBot(ua:string){return /bot|crawler|spider|curl|wget|python|scanner|headless|scrapy|httpclient/i.test(ua)} function uaClass(ua:string){if(/mobile|iphone|android/i.test(ua))return 'mobile'; if(isBot(ua))return 'bot'; if(/mozilla|chrome|safari|firefox|edge/i.test(ua))return 'browser'; return 'agent'}
function validateUrl(u:string,mode='redirect'){let url:URL;try{url=new URL(u)}catch{return 'destinationUrl must be a valid URL'} if(!['https:','http:'].includes(url.protocol))return 'Only http/https URLs are supported'; if(mode==='proxy'&&/(^localhost$|\.local$|\.internal$|^127\.|^10\.|^192\.168\.|^169\.254\.|^172\.(1[6-9]|2\d|3[01])\.)/i.test(url.hostname))return 'Proxy target blocked by SSRF policy'; return null}
async function audit(env:Env,actor:string,action:string,aliasId:string|null,detail:unknown){await env.DB.prepare('INSERT INTO audit_events(id,timestamp_utc,actor,action,alias_id,detail) VALUES(?,?,?,?,?,?)').bind(id('audit'),now(),actor,action,aliasId,JSON.stringify(detail||{})).run().catch(()=>{})}
async function event(env:Env,req:Request,resourceId:string|null,type:string,decision:string,status:number,reason:string,start:number,tenantId:string|null=null){const u=new URL(req.url), ip=req.headers.get('cf-connecting-ip')||'', ua=req.headers.get('user-agent')||''; await env.DB.prepare(`INSERT INTO alias_events(id,alias_id,event_type,timestamp_utc,method,path,redacted_query,ip_hash,country,colo,user_agent_hash,user_agent_summary,referrer_host,origin,status_code,decision,reason,latency_ms,request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(id('evt'),resourceId,type,now(),req.method,u.pathname,u.search?'present':'',ip?await sha(ip):'',req.cf?.country||'',(req.cf as any)?.colo||'',ua?await sha(ua):'',uaClass(ua),host(req.headers.get('referer')),req.headers.get('origin')||'',status,decision,reason,Date.now()-start,req.headers.get('cf-ray')||id('req')).run().catch(()=>{})}
function targetWithQuery(target:string,reqUrl:URL,a:Alias){const u=new URL(target); if(a.preserve_query_string){for(const [k,v]of reqUrl.searchParams)if(!u.searchParams.has(k))u.searchParams.append(k,v)} const utm=parseJson<Record<string,string>>(a.utm_config,{}); Object.entries(utm).forEach(([k,v])=>u.searchParams.set(k,v)); return u.toString()}
async function lookupAlias(env:Env,ns:string,slug:string){const key=`${ns}:${slug}`; const c=await env.ALIAS_CACHE.get(key,'json') as any; if(c?.alias)return c as {alias:Alias,policy:Policy|null}; const alias=await env.DB.prepare('SELECT * FROM aliases WHERE namespace=? AND slug=?').bind(ns,slug).first<Alias>(); if(!alias)return null; const policy=await env.DB.prepare('SELECT * FROM alias_policies WHERE alias_id=?').bind(alias.id).first<Policy>(); await env.ALIAS_CACHE.put(key,JSON.stringify({alias,policy}),{expirationTtl:60}); return {alias,policy}}
async function resolveAlias(req:Request,env:Env,ns:string,slug:string,start:number){const f=await lookupAlias(env,ns,slug); if(!f){await event(env,req,null,'link.visit','not_found',404,'not found',start);return branded('Alias not found','This edge alias does not exist.',404)} const {alias:a,policy:p}=f; let reason='OK', status=200, decision='allowed'; if(!a.is_active||a.mode==='disabled'){status=410;decision='disabled';reason='Alias disabled'} else if(a.expires_utc&&Date.parse(a.expires_utc)<=Date.now()){status=410;decision='expired';reason='Alias expired'} else if(a.max_views!=null&&a.view_count>=a.max_views){status=410;decision='expired';reason='Max clicks reached'} else if(p){const methods=arr(p.allowed_methods); const origin=req.headers.get('origin')||''; const ref=host(req.headers.get('referer')); if(methods.length&&!methods.includes(req.method)){status=405;decision='denied';reason='Method not allowed'} else if(arr(p.allowed_origins).length&&origin&&!arr(p.allowed_origins).includes(origin)){status=403;decision='denied';reason='Origin denied'} else if(arr(p.allowed_referrers).length&&ref&&!arr(p.allowed_referrers).includes(ref)){status=403;decision='denied';reason='Referrer denied'} else if((p.block_bots||(p.block_likely_bots_for_post&&req.method!=='GET'))&&isBot(req.headers.get('user-agent')||'')){status=403;decision='bot_blocked';reason='Bot blocked'}} if(status!==200){await event(env,req,a.id,'link.visit',decision,status,reason,start,a.api_tenant_id||null);return branded(reason,`/${a.namespace}/${a.slug}`,status)} await env.DB.prepare('UPDATE aliases SET view_count=view_count+1,last_access_utc=?,success_count=success_count+1 WHERE id=?').bind(now(),a.id).run(); await env.ALIAS_CACHE.delete(`${a.namespace}:${a.slug}`); if((req.headers.get('accept')||'').includes('application/json')||a.mode==='metadata'){await event(env,req,a.id,'link.metadata','allowed',200,'metadata',start,a.api_tenant_id||null);return rawjson({alias:a.slug,namespace:a.namespace,destinationUrl:a.target_url,enabled:!!a.is_active,expiresUtc:a.expires_utc,tags:parseJson(a.tags,[])})} const loc=targetWithQuery(a.target_url,new URL(req.url),a); await event(env,req,a.id,'link.visit','redirected',a.redirect_status_code,'redirected',start,a.api_tenant_id||null); return Response.redirect(loc,a.redirect_status_code as 301|302|303|307|308)}
async function auth(req:Request,env:Env,scope?:string):Promise<Auth|Response>{const h=req.headers.get('authorization')||''; const token=h.startsWith('Bearer ')?h.slice(7):req.headers.get('x-api-key')||''; if(!token)return err('unauthorized','API key required.',401); const hash=await sha(token); const row=await env.DB.prepare('SELECT k.id key_id,k.scopes,k.is_active,t.* FROM api_keys k JOIN tenants t ON t.id=k.tenant_id WHERE k.key_hash=?').bind(hash).first<any>(); if(!row||!row.is_active||!row.is_active)return err('unauthorized','Invalid or revoked API key.',401); const scopes=parseJson<string[]>(row.scopes,[]); if(scope&&!scopes.includes(scope)&&!scopes.includes('admin'))return err('forbidden',`Missing scope ${scope}.`,403); await env.DB.prepare('UPDATE api_keys SET last_used_utc=? WHERE id=?').bind(now(),row.key_id).run().catch(()=>{}); return {tenant:row as Tenant,keyId:row.key_id,scopes}}
async function adminOk(req:Request,env:Env){const c=req.headers.get('cookie')||''; const m=c.match(/(?:^|; )admin_session=([^;]+)/); if(!m||!env.ADMIN_PASSWORD)return false; return await sha(env.ADMIN_PASSWORD)===m[1]}
function signIn(){return html(page(`<main class="hero"><section class="card" style="max-width:520px;margin:auto"><p class="brand">1db.io</p><h1>Sign in</h1><p class="muted">Sign in to manage private 1db resources.</p><form method="post" action="/signin"><label>Password <input name="password" type="password" autocomplete="current-password"></label><button>Sign in</button></form></section></main>`,'Sign in'))}
async function signInPost(req:Request,env:Env){const fd=await req.formData(); const pass=String(fd.get('password')||''); if(!env.ADMIN_PASSWORD||await sha(pass)!==await sha(env.ADMIN_PASSWORD))return html(page(`<main class="hero"><section class="card"><h1>Sign in failed</h1><p class="muted">Invalid password.</p><p><a class="btn" href="/signin">Try again</a></p></section></main>`),401); return new Response(null,{status:303,headers:{location:'/admin','set-cookie':`admin_session=${await sha(env.ADMIN_PASSWORD)}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=28800`}})}
async function admin(req:Request,env:Env){if(!await adminOk(req,env))return signIn(); return html(page(`<main><p class="brand">1db.io control</p><div class="grid"><section class="card"><h1>Create Edge Link</h1><label>API token <input id="tok" type="password" placeholder="1db_live_..."></label><div class="row"><label>Code <input id="al" placeholder="launch"></label><label>Destination URL <input id="target" value="https://example.com/campaign"></label></div><button onclick="createAlias()">Create short link</button><p id="msg" class="muted"></p></section><section class="card"><h2>Links</h2><input id="q" placeholder="Search" oninput="loadAliases()"><div id="list"></div></section></div><section class="card"><h2>Detail / analytics</h2><div id="detail" class="muted">Select a link.</div></section></main><script>${adminJs()}</script>`,'Control'))}
function adminJs(){return `const H=()=>({'content-type':'application/json','authorization':'Bearer '+document.getElementById('tok').value}); async function createAlias(){msg.textContent='Creating...'; const r=await fetch('/api/v1/links',{method:'POST',headers:H(),body:JSON.stringify({code:al.value,destinationUrl:target.value,tags:['dashboard']})}); const j=await r.json(); msg.textContent=r.ok?'Created '+j.data.shortUrl:(j.error&&j.error.message); loadAliases()} async function loadAliases(){const r=await fetch('/api/v1/links?q='+encodeURIComponent(q.value),{headers:H()}); if(!r.ok){list.innerHTML='<p class=muted>Enter API key to load links.</p>';return} const j=await r.json(); list.innerHTML='<table><tr><th>Link</th><th>Clicks</th><th></th></tr>'+j.data.items.map(a=>'<tr><td><code>'+a.shortUrl+'</code></td><td>'+a.clicks+'</td><td><button onclick="detailAlias(\\''+a.id+'\\')">Open</button></td></tr>').join('')+'</table>'} async function detailAlias(id){const [a,an]=await Promise.all([fetch('/api/v1/links/'+id,{headers:H()}).then(r=>r.json()),fetch('/api/v1/analytics/links/'+id,{headers:H()}).then(r=>r.json())]); detail.innerHTML='<h3>'+a.data.shortUrl+'</h3><p>'+a.data.destinationUrl+'</p><pre>'+JSON.stringify(an,null,2)+'</pre>'}`}

type Visibility={scope:string;allowedActorIds?:string[];deniedActorIds?:string[];sensitivity?:string;retention?:string;userMutable?:boolean};
type MemoryRow={id:string;tenant_id:string;owner_id?:string|null;project_id?:string|null;conversation_id?:string|null;kind:string;canonical_text:string;raw_text?:string|null;confidence:number;salience:number;utility_score?:number|null;emotional_weight?:number|null;status:string;supersedes?:string|null;superseded_by?:string|null;temporal:string;access:string;metadata?:string|null;created_at:string;updated_at:string};
const DEFAULT_VIS:Visibility={scope:'project',sensitivity:'normal',retention:'project_lifetime',userMutable:true};
const COG_EVENT_TYPES=new Set(['conversation.message','agent.observation','agent.decision','tool.call','tool.result','memory.extracted','memory.confirmed','memory.corrected','memory.deprecated','task.created','task.updated','relationship.changed','identity.updated','preference.learned','state.snapshot']);
const COG_KINDS=new Set(['decision','fact','constraint','open_question','task','preference','artifact_reference']);
function visibility(v:any):Visibility{return {...DEFAULT_VIS,...(v||{})}}
function canSee(access:any,actorId:string){const v=visibility(typeof access==='string'?parseJson(access,{}):access); if((v.deniedActorIds||[]).includes(actorId))return false; if(v.allowedActorIds?.length&&!v.allowedActorIds.includes(actorId))return false; if(v.scope==='private_user'||v.scope==='private_agent')return (v.allowedActorIds||[]).includes(actorId); return true}
function contributesToProjectContinuity(access:any){const v=visibility(typeof access==='string'?parseJson(access,{}):access); return !['private_user','private_agent'].includes(v.scope)}
function canonicalEntityName(s:string){return clean(s).replace(/_/g,'-')||'unknown'}
function tokenize(s:string){return new Set((s.toLowerCase().match(/[a-z0-9]{3,}/g)||[]).slice(0,200))}
function lexicalSimilarity(a:string,b:string){const A=tokenize(a),B=tokenize(b); if(!A.size||!B.size)return 0; let hit=0; for(const x of A)if(B.has(x))hit++; return hit/Math.sqrt(A.size*B.size)}
function lexicalEmbedding(text:string){const words=[...tokenize(text)].sort(); return JSON.stringify({kind:'lexical_terms',terms:words.slice(0,64)})}
function memoryOut(m:MemoryRow){return {id:m.id,kind:m.kind,tenantId:m.tenant_id,ownerId:m.owner_id,projectId:m.project_id,conversationId:m.conversation_id,canonicalText:m.canonical_text,rawText:m.raw_text,confidence:m.confidence,salience:m.salience,status:m.status,temporal:parseJson(m.temporal,{}),access:parseJson(m.access,{}),metadata:parseJson(m.metadata,{})}}
function continuityDefault(projectId:string):any{return {projectId,currentGoals:[],activeDecisions:[],unresolvedQuestions:[],activeTasks:[],blockedTasks:[],constraints:[],artifactReferences:[],importantEntities:[],recentChanges:[],memorySummary:'No durable project memory yet.',lastUpdatedAt:now()}}
function addUnique(a:string[],v:string){if(v&&!a.includes(v))a.push(v); return a.slice(-50)}
async function upsertEntity(env:Env,tenantId:string,type:string,name:string){const canon=canonicalEntityName(name); const eid=`ent_${await sha(`${tenantId}:${type}:${canon}`).then(x=>x.slice(0,24))}`; await env.DB.prepare('INSERT OR IGNORE INTO cognitive_entities(id,tenant_id,type,name,canonical_name,aliases,metadata,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?)').bind(eid,tenantId,type,name,canon,JSON.stringify([]),JSON.stringify({}),now(),now()).run(); return {id:eid,type,name,canonicalName:canon}}
function extractEntities(text:string,projectId?:string){const out:{type:string;name:string}[]=[]; if(projectId)out.push({type:'Project',name:projectId}); for(const m of text.matchAll(/\b[A-Z][A-Za-z0-9_.-]{2,}\b/g)){const name=m[0]; if(!['User','The','This','For','MVP'].includes(name))out.push({type:'Concept',name})} return out.slice(0,12)}
function extractCandidates(event:any){const text=String(event.payload?.text||event.payload?.message||event.payload?.summary||'').trim(); if(!text)return []; const candidates:any[]=[]; const sentences=text.split(/(?<=[.!?])\s+/).map(x=>x.trim()).filter(Boolean); const add=(kind:string,canonicalText:string,confidence=.82,salience=.7)=>candidates.push({kind,canonicalText,rawText:text,evidenceEventIds:[event.id],entities:extractEntities(canonicalText,event.projectId),relations:[],confidence,suggestedSalience:salience,persistenceRecommendation:confidence>=.75?'durable_active':'durable_tentative'});
 if(/\b(decided|decision|must include|architecture)\b/i.test(text))add('decision', text.match(/decided\s+(.*)/i)?.[1]?.replace(/^that\s+/i,'') || text, .9, .85);
 if(/\b(MVP|must|should|constraint|requirement|required|focus)\b/i.test(text))add('constraint', text.match(/MVP[^.?!]*/i)?.[0] || text, .84, .8);
 if(/\b(todo|task|next|implement|build|add|fix|follow up)\b/i.test(text))add('task', text, .72, .74);
 if(/\?/.test(text)||/\b(unresolved|open question|unknown|gap)\b/i.test(text))add('open_question', sentences.find(x=>x.includes('?'))||text, .7, .68);
 if(/\b(prefer|preference|likes|wants|style)\b/i.test(text))add('preference', text, .76, .7);
 if(/\b(fact|applies to|is|are)\b/i.test(text)&&/\bproject|1db\b/i.test(text))add('fact', text, .72, .62);
 for(const url of text.match(/https?:\/\/\S+|[\w./-]+\.(ts|md|sql|json|toml|js)/g)||[])add('artifact_reference', url, .88, .7);
 const seen=new Set(); return candidates.filter(c=>COG_KINDS.has(c.kind)&&!seen.has(c.kind+'|'+c.canonicalText)&&seen.add(c.kind+'|'+c.canonicalText));}
async function storeMemory(env:Env,event:any,c:any,access:Visibility){const mid=id('mem'), t=now(), status=c.persistenceRecommendation==='durable_tentative'?'tentative':'active'; await env.DB.prepare('INSERT INTO memory_atoms(id,tenant_id,owner_id,project_id,conversation_id,kind,canonical_text,raw_text,confidence,salience,status,supersedes,superseded_by,temporal,access,metadata,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(mid,event.tenantId,event.subjectId||null,event.projectId||null,event.conversationId||null,c.kind,c.canonicalText,c.rawText||null,c.confidence,c.suggestedSalience,status,JSON.stringify([]),JSON.stringify([]),JSON.stringify({createdAt:t,observedAt:event.timestamp||t}),JSON.stringify(access),JSON.stringify({extractor:'rule_mvp'}),t,t).run(); await env.DB.prepare('INSERT INTO memory_evidence(id,memory_id,event_id,tenant_id,excerpt,evidence_role,confidence,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(id('evd'),mid,event.id,event.tenantId,c.canonicalText.slice(0,1000),'source',1,t).run(); await env.DB.prepare('INSERT INTO memory_embeddings(id,memory_id,tenant_id,embedding_json,embedding_model,embedded_text,created_at) VALUES(?,?,?,?,?,?,?)').bind(id('emb'),mid,event.tenantId,lexicalEmbedding(c.canonicalText),'lexical-mvp',c.canonicalText,t).run(); for(const e of c.entities||[]){const ent=await upsertEntity(env,event.tenantId,e.type,e.name); await env.DB.prepare('INSERT INTO cognitive_edges(id,tenant_id,from_node_id,to_node_id,from_node_type,to_node_type,type,confidence,weight,evidence_event_ids,memory_ids,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id('edge'),event.tenantId,mid,ent.id,'Memory',e.type,'MENTIONED_IN',c.confidence,c.suggestedSalience,JSON.stringify([event.id]),JSON.stringify([mid]),status,t,t).run()} return mid}
async function updateContinuity(env:Env,tenantId:string,projectId:string|undefined,memory?:MemoryRow|any,eventIds:string[]=[]){if(!projectId)return null; const current=await env.DB.prepare('SELECT * FROM continuity_states WHERE tenant_id=? AND scope_type=? AND scope_id=?').bind(tenantId,'project',projectId).first<any>(); const state=current?parseJson<any>(current.state,continuityDefault(projectId)):continuityDefault(projectId); if(memory){const text=memory.canonical_text||memory.canonicalText; if(memory.status&& !['active','tentative'].includes(memory.status)){} else if(memory.kind==='decision')state.activeDecisions=addUnique(state.activeDecisions,text); else if(memory.kind==='open_question')state.unresolvedQuestions=addUnique(state.unresolvedQuestions,text); else if(memory.kind==='task')state.activeTasks=addUnique(state.activeTasks,text); else if(memory.kind==='constraint')state.constraints=addUnique(state.constraints,text); else if(memory.kind==='artifact_reference')state.artifactReferences=addUnique(state.artifactReferences,text); state.recentChanges=[{changedAt:now(),description:`${memory.kind}: ${text}`,eventIds},...state.recentChanges].slice(0,20)} state.lastUpdatedAt=now(); state.memorySummary=[state.activeDecisions.length?`Decisions: ${state.activeDecisions.slice(-3).join(' | ')}`:'',state.constraints.length?`Constraints: ${state.constraints.slice(-3).join(' | ')}`:'',state.activeTasks.length?`Tasks: ${state.activeTasks.slice(-3).join(' | ')}`:'',state.unresolvedQuestions.length?`Open questions: ${state.unresolvedQuestions.slice(-3).join(' | ')}`:''].filter(Boolean).join('\n')||'No durable project memory yet.'; const csid=current?.id||id('state'); await env.DB.prepare('INSERT INTO continuity_states(id,tenant_id,scope_type,scope_id,state,summary,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(tenant_id,scope_type,scope_id) DO UPDATE SET state=excluded.state, summary=excluded.summary, version=continuity_states.version+1, updated_at=excluded.updated_at').bind(csid,tenantId,'project',projectId,JSON.stringify(state),state.memorySummary,current?current.version+1:1,current?.created_at||now(),now()).run(); return state}

async function rebuildContinuity(env:Env,tenantId:string,projectId:string|undefined){if(!projectId)return null; const rs=await env.DB.prepare('SELECT * FROM memory_atoms WHERE tenant_id=? AND project_id=? AND status IN ("active","tentative") ORDER BY created_at ASC').bind(tenantId,projectId).all<MemoryRow>(); const state=continuityDefault(projectId); for(const m of rs.results){if(!contributesToProjectContinuity(m.access))continue; const text=m.canonical_text; if(m.kind==='decision')state.activeDecisions=addUnique(state.activeDecisions,text); else if(m.kind==='open_question')state.unresolvedQuestions=addUnique(state.unresolvedQuestions,text); else if(m.kind==='task')state.activeTasks=addUnique(state.activeTasks,text); else if(m.kind==='constraint')state.constraints=addUnique(state.constraints,text); else if(m.kind==='artifact_reference')state.artifactReferences=addUnique(state.artifactReferences,text); state.recentChanges=[{changedAt:m.updated_at,description:`${m.kind}: ${text}`,eventIds:[]},...state.recentChanges].slice(0,20)} state.lastUpdatedAt=now(); state.memorySummary=[state.activeDecisions.length?`Decisions: ${state.activeDecisions.slice(-3).join(' | ')}`:'',state.constraints.length?`Constraints: ${state.constraints.slice(-3).join(' | ')}`:'',state.activeTasks.length?`Tasks: ${state.activeTasks.slice(-3).join(' | ')}`:'',state.unresolvedQuestions.length?`Open questions: ${state.unresolvedQuestions.slice(-3).join(' | ')}`:''].filter(Boolean).join('\n')||'No durable project memory yet.'; const current=await env.DB.prepare('SELECT * FROM continuity_states WHERE tenant_id=? AND scope_type=? AND scope_id=?').bind(tenantId,'project',projectId).first<any>(); await env.DB.prepare('INSERT INTO continuity_states(id,tenant_id,scope_type,scope_id,state,summary,version,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(tenant_id,scope_type,scope_id) DO UPDATE SET state=excluded.state, summary=excluded.summary, version=continuity_states.version+1, updated_at=excluded.updated_at').bind(current?.id||id('state'),tenantId,'project',projectId,JSON.stringify(state),state.memorySummary,current?current.version+1:1,current?.created_at||now(),now()).run(); return state}

async function ingestCognitive(env:Env,authn:Auth,input:any){if(!COG_EVENT_TYPES.has(input.type))throw new Error('invalid_event_type'); const tenantId=authn.tenant.id, ev={...input,id:id('cevt'),tenantId,actorId:input.actorId||authn.keyId,timestamp:now(),source:{kind:input.source?.kind||'agent',...(input.source||{})},visibility:visibility(input.visibility),audit:{createdBy:input.audit?.createdBy||authn.keyId,reason:input.audit?.reason||'api_ingest'}}; const checksum=await sha(JSON.stringify({type:ev.type,payload:ev.payload,timestamp:ev.timestamp})); ev.audit.checksum=checksum; await env.DB.prepare('INSERT INTO cognitive_events(id,type,tenant_id,actor_id,subject_id,session_id,conversation_id,project_id,workflow_id,source_kind,source_id,source_confidence,payload,visibility,lineage,audit,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(ev.id,ev.type,tenantId,ev.actorId,input.subjectId||null,input.sessionId||null,input.conversationId||null,input.projectId||null,input.workflowId||null,ev.source.kind,ev.source.id||null,ev.source.confidence||null,JSON.stringify(input.payload||{}),JSON.stringify(ev.visibility),JSON.stringify(input.lineage||{}),JSON.stringify(ev.audit),ev.timestamp).run(); const candidates=extractCandidates(ev); const memories:string[]=[]; for(const c of candidates){if(c.persistenceRecommendation.startsWith('durable')){const mid=await storeMemory(env,ev,c,ev.visibility); memories.push(mid); const row=await env.DB.prepare('SELECT * FROM memory_atoms WHERE id=?').bind(mid).first<MemoryRow>(); if(row&&contributesToProjectContinuity(row.access))await updateContinuity(env,tenantId,input.projectId,row,[ev.id]);}} if(!memories.length)await updateContinuity(env,tenantId,input.projectId,undefined,[ev.id]); return {event:ev,extractedMemoryIds:memories,candidates}}
async function retrieveCognitive(env:Env,authn:Auth,input:any){const intent=input.intent||'continue_project', max=input.limits?.maxMemories||20; const cont=input.projectId?await env.DB.prepare('SELECT * FROM continuity_states WHERE tenant_id=? AND scope_type=? AND scope_id=?').bind(authn.tenant.id,'project',input.projectId).first<any>():null; const state=cont?parseJson<any>(cont.state,{}):{}; const rs=await env.DB.prepare('SELECT * FROM memory_atoms WHERE tenant_id=? AND (? IS NULL OR project_id=?) AND status NOT IN ("deprecated","deleted","superseded") ORDER BY updated_at DESC LIMIT 200').bind(authn.tenant.id,input.projectId||null,input.projectId||null).all<MemoryRow>(); const visible=rs.results.filter(m=>canSee(m.access,input.actorId||authn.keyId)); const scored=visible.map(m=>({m,score:.35*lexicalSimilarity(m.canonical_text,input.query||'')+.15*m.salience+.10*m.confidence+.10*(m.kind==='task'&&intent==='plan_next_step'?1:0)+.10*(['decision','constraint','open_question','task'].includes(m.kind)?1:0)})).sort((a,b)=>b.score-a.score).slice(0,max).map(x=>x.m); const evid= scored.length? await env.DB.prepare(`SELECT * FROM memory_evidence WHERE tenant_id=? AND memory_id IN (${scored.map(()=>'?').join(',')})`).bind(authn.tenant.id,...scored.map(m=>m.id)).all<any>():{results:[]}; return {summary:state.memorySummary||cont?.summary||'No continuity state found.',memories:scored.map(memoryOut),activeState:{activeGoals:state.currentGoals||[],activeTasks:state.activeTasks||[],openQuestions:state.unresolvedQuestions||[],recentDecisions:state.activeDecisions||[],constraints:state.constraints||[]},graphContext:{entities:state.importantEntities||[],relationships:[]},warnings:visible.length<rs.results.length?[{type:'permission_filtered',message:'Some memories were filtered by access policy.'}]:[],provenance:evid.results}}
async function correctCognitive(env:Env,authn:Auth,memoryId:string,input:any){const old=await env.DB.prepare('SELECT * FROM memory_atoms WHERE id=? AND tenant_id=?').bind(memoryId,authn.tenant.id).first<MemoryRow>(); if(!old)return null; if(!canSee(old.access,input.actorId||authn.keyId))throw new Error('forbidden'); const evIn={type:'memory.corrected',actorId:input.actorId||authn.keyId,projectId:old.project_id,payload:{memoryId,correction:input.correction,reason:input.reason},visibility:parseJson(old.access,DEFAULT_VIS),lineage:{derivedFromMemoryIds:[memoryId]}}; const res=await ingestCognitive(env,authn,evIn); const mid=id('mem'), t=now(); await env.DB.prepare('UPDATE memory_atoms SET status="superseded", superseded_by=?, updated_at=? WHERE id=?').bind(JSON.stringify([mid]),t,memoryId).run(); await env.DB.prepare('INSERT INTO memory_atoms(id,tenant_id,owner_id,project_id,conversation_id,kind,canonical_text,raw_text,confidence,salience,status,supersedes,superseded_by,temporal,access,metadata,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(mid,authn.tenant.id,old.owner_id,old.project_id,old.conversation_id,old.kind,String(input.correction),old.raw_text,0.95,Math.max(old.salience,.8),'active',JSON.stringify([memoryId]),JSON.stringify([]),JSON.stringify({createdAt:t,observedAt:t}),old.access,JSON.stringify({correctionReason:input.reason||'correction',correctedFrom:memoryId}),t,t).run(); await env.DB.prepare('INSERT INTO memory_evidence(id,memory_id,event_id,tenant_id,excerpt,evidence_role,confidence,created_at) VALUES(?,?,?,?,?,?,?,?)').bind(id('evd'),mid,res.event.id,authn.tenant.id,String(input.correction).slice(0,1000),'correction',1,t).run(); await env.DB.prepare('INSERT INTO memory_embeddings(id,memory_id,tenant_id,embedding_json,embedding_model,embedded_text,created_at) VALUES(?,?,?,?,?,?,?)').bind(id('emb'),mid,authn.tenant.id,lexicalEmbedding(String(input.correction)),'lexical-mvp',String(input.correction),t).run(); const row=await env.DB.prepare('SELECT * FROM memory_atoms WHERE id=?').bind(mid).first<MemoryRow>(); await rebuildContinuity(env,authn.tenant.id,old.project_id||undefined); return row?memoryOut(row):null}
async function deprecateCognitive(env:Env,authn:Auth,memoryId:string,input:any){const old=await env.DB.prepare('SELECT * FROM memory_atoms WHERE id=? AND tenant_id=?').bind(memoryId,authn.tenant.id).first<MemoryRow>(); if(!old)return null; if(!canSee(old.access,input.actorId||authn.keyId))throw new Error('forbidden'); const res=await ingestCognitive(env,authn,{type:'memory.deprecated',actorId:input.actorId||authn.keyId,projectId:old.project_id,payload:{memoryId,reason:input.reason},visibility:parseJson(old.access,DEFAULT_VIS),lineage:{derivedFromMemoryIds:[memoryId]}}); await env.DB.prepare('UPDATE memory_atoms SET status="deprecated", updated_at=? WHERE id=?').bind(now(),memoryId).run(); await rebuildContinuity(env,authn.tenant.id,old.project_id||undefined); return {...memoryOut(old),status:'deprecated'}}
async function explainCognitive(env:Env,authn:Auth,memoryId:string){const m=await env.DB.prepare('SELECT * FROM memory_atoms WHERE id=? AND tenant_id=?').bind(memoryId,authn.tenant.id).first<MemoryRow>(); if(!m)return null; if(!canSee(m.access,authn.keyId))throw new Error('forbidden'); const ev=await env.DB.prepare('SELECT e.event_id,e.excerpt,e.evidence_role,e.confidence,c.created_at,c.source_kind FROM memory_evidence e JOIN cognitive_events c ON c.id=e.event_id WHERE e.memory_id=?').bind(memoryId).all<any>(); const related=await env.DB.prepare('SELECT * FROM memory_atoms WHERE tenant_id=? AND project_id IS ? AND id<>? AND status<>"deleted" ORDER BY updated_at DESC LIMIT 10').bind(authn.tenant.id,m.project_id,memoryId).all<MemoryRow>(); return {memory:memoryOut(m),explanation:`Remembered as ${m.kind} because ${ev.results.length} evidence event(s) support it. Status is ${m.status}; confidence ${m.confidence}; salience ${m.salience}.`,evidence:ev.results.map((e:any)=>({eventId:e.event_id,timestamp:e.created_at,source:e.source_kind,excerpt:e.excerpt})),relatedMemories:related.results.filter(r=>canSee(r.access,authn.keyId)).map(memoryOut),lifecycle:{createdAt:m.created_at,lastReinforcedAt:parseJson<any>(m.temporal,{}).lastReinforcedAt,supersededBy:parseJson(m.superseded_by,[])}}}
async function cognitionApi(req:Request,env:Env,parts:string[],start:number){const method=req.method; const scope=method==='GET'?'cognition:read':'cognition:write'; const a=await auth(req,env,scope); if(a instanceof Response)return a; try{if(parts[0]==='events'&&method==='POST')return ok(await ingestCognitive(env,a,await req.json<any>()),201); if(parts[0]==='context'&&parts[1]==='retrieve'&&method==='POST')return ok(await retrieveCognitive(env,a,await req.json<any>())); if(parts[0]==='projects'&&parts[2]==='continuity'&&method==='GET'){const cs=await env.DB.prepare('SELECT * FROM continuity_states WHERE tenant_id=? AND scope_type="project" AND scope_id=?').bind(a.tenant.id,parts[1]).first<any>(); return ok(cs?{...cs,state:parseJson(cs.state,{})}:null)} if(parts[0]==='memories'&&parts[2]==='correct'&&method==='PATCH'){const r=await correctCognitive(env,a,parts[1],await req.json<any>()); return r?ok(r):err('not_found','Memory not found.',404)} if(parts[0]==='memories'&&parts[2]==='deprecate'&&method==='PATCH'){const r=await deprecateCognitive(env,a,parts[1],await req.json<any>()); return r?ok(r):err('not_found','Memory not found.',404)} if(parts[0]==='memories'&&parts[2]==='explain'&&method==='GET'){const r=await explainCognitive(env,a,parts[1]); return r?ok(r):err('not_found','Memory not found.',404)}}catch(e:any){return err(e.message==='forbidden'?'forbidden':'invalid_request',e.message||'Cognition request failed',e.message==='forbidden'?403:400)} return err('not_found','Cognition route not found.',404)}

