 if(parts[0]==='links'){const a=await auth(req,env,method==='POST'?'links:create':method==='GET'?'links:read':method==='PATCH'?'links:update':'links:delete'); if(a instanceof Response)return a; if(method==='POST'&&!parts[1]){const b=await req.json<any>(); const code=clean(b.code||Math.random().toString(36).slice(2,8)); const dest=b.destinationUrl; const bad=validateUrl(dest); if(bad)return err('invalid_request',bad,400); const aid=id('link'), t=now(), short=`${env.PUBLIC_ORIGIN}/a/${code}`; await env.DB.prepare(`INSERT INTO aliases(id,public_code,namespace,slug,canonical_short_url,target_url,target_type,mode,redirect_status_code,preserve_query_string,is_active,created_utc,updated_utc,expires_utc,max_views,metadata,api_tenant_id,tags,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`).bind(aid,`a/${code}`,'a',code,short,dest,'link','redirect',302,1,b.enabled===false?0:1,t,t,b.expiresUtc||null,b.maxClicks??null,JSON.stringify(b.metadata||{}),a.tenant.id,JSON.stringify(b.tags||[]),b.notes||null).run(); await env.DB.prepare(`INSERT INTO alias_policies(id,alias_id,allowed_origins,allowed_referrers,allowed_methods,block_bots,block_likely_bots_for_post,one_time_use) VALUES(?,?,?,?,?,?,?,?)`).bind(id('pol'),aid,JSON.stringify(b.allowedOrigins||[]),JSON.stringify(b.allowedReferrers||[]),JSON.stringify(['GET','HEAD']),0,1,0).run(); await audit(env,a.keyId,'links.create',aid,{code}); return ok({id:aid,code,shortUrl:short,destinationUrl:dest,enabled:b.enabled!==false},201)} if(method==='GET'&&!parts[1]){const rs=await env.DB.prepare('SELECT * FROM aliases WHERE api_tenant_id=? AND namespace="a" ORDER BY updated_utc DESC LIMIT 100').bind(a.tenant.id).all<Alias>(); return ok({items:rs.results.map(linkOut),hasMore:false})} const link=await env.DB.prepare('SELECT * FROM aliases WHERE id=? AND api_tenant_id=?').bind(parts[1],a.tenant.id).first<Alias>(); if(!link)return err('not_found','Link not found.',404); if(method==='GET')return ok(linkOut(link)); if(method==='PATCH'){const b=await req.json<any>(); const dest=b.destinationUrl||link.target_url; const bad=validateUrl(dest); if(bad)return err('invalid_request',bad,400); await env.DB.prepare('UPDATE aliases SET target_url=?,is_active=?,expires_utc=?,max_views=?,tags=?,notes=?,updated_utc=? WHERE id=?').bind(dest,b.enabled===undefined?link.is_active:(b.enabled?1:0),b.expiresUtc??link.expires_utc,b.maxClicks??link.max_views,b.tags?JSON.stringify(b.tags):link.tags,b.notes??link.notes,now(),link.id).run(); await env.ALIAS_CACHE.delete(`a:${link.slug}`); return ok({id:link.id,updated:true})} if(method==='DELETE'){await env.DB.prepare('UPDATE aliases SET is_active=0,mode="disabled",updated_utc=? WHERE id=?').bind(now(),link.id).run(); await env.ALIAS_CACHE.delete(`a:${link.slug}`); return ok({id:link.id,deleted:true})}}
 if(parts[0]==='routes'){const a=await auth(req,env,method==='POST'?'routes:create':method==='GET'?'routes:read':method==='PATCH'?'routes:update':'routes:delete'); if(a instanceof Response)return a; if(method==='POST'&&!parts[1]){const b=await req.json<any>(); const rid=id('route'), path='r/'+clean((b.publicPath||b.slug||rid).replace(/^\/+/,'').replace(/^r\//,'')), t=now(); await env.DB.prepare('INSERT INTO routes(id,tenant_id,public_path,type,target_url,allowed_methods,auth_policy,cors_policy,origin_restrictions,rate_limit_per_minute,request_logging,bot_protection,persist_payload,static_status,static_body,is_active,created_utc,updated_utc,metadata) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(rid,a.tenant.id,path,b.type||'static-response',b.targetUrl||null,JSON.stringify(b.allowedMethods||['GET','POST']),JSON.stringify(b.authPolicy||{}),JSON.stringify(b.corsPolicy||{}),JSON.stringify(b.originRestrictions||[]),b.rateLimitPerMinute||null,1,b.botProtection===false?0:1,b.persistPayload?1:0,b.staticStatus||200,b.staticBody||null,1,t,t,JSON.stringify(b.metadata||{})).run(); return ok({id:rid,publicPath:`/${path}`,url:`${env.PUBLIC_ORIGIN}/${path}`,type:b.type||'static-response'},201)} if(method==='GET'&&!parts[1]){const rs=await env.DB.prepare('SELECT * FROM routes WHERE tenant_id=? ORDER BY updated_utc DESC LIMIT 100').bind(a.tenant.id).all(); return ok({items:rs.results})} const route=await env.DB.prepare('SELECT * FROM routes WHERE id=? AND tenant_id=?').bind(parts[1],a.tenant.id).first<any>(); if(!route)return err('not_found','Route not found.',404); if(method==='GET')return ok(route); if(method==='PATCH'){const b=await req.json<any>(); await env.DB.prepare('UPDATE routes SET type=?,target_url=?,allowed_methods=?,is_active=?,updated_utc=? WHERE id=?').bind(b.type||route.type,b.targetUrl??route.target_url,b.allowedMethods?JSON.stringify(b.allowedMethods):route.allowed_methods,b.enabled===undefined?route.is_active:(b.enabled?1:0),now(),route.id).run(); return ok({id:route.id,updated:true})} if(method==='DELETE'){await env.DB.prepare('UPDATE routes SET is_active=0,updated_utc=? WHERE id=?').bind(now(),route.id).run(); return ok({id:route.id,deleted:true})}}
 if(parts[0]==='intakes'){const a=await auth(req,env,method==='POST'?'intakes:create':'intakes:read'); if(a instanceof Response)return a; if(method==='POST'&&!parts[1]){const b=await req.json<any>(); const iid=id('intake'), slug=clean(b.slug||b.name||Math.random().toString(36).slice(2,8)), path=`i/${a.tenant.slug}/${slug}`, t=now(); await env.DB.prepare('INSERT INTO intakes(id,tenant_id,slug,public_path,name,schema_json,allowed_origins,bot_protection,honeypot_field,is_active,created_utc,updated_utc,metadata) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(iid,a.tenant.id,slug,path,b.name||slug,JSON.stringify(b.schema||{}),JSON.stringify(b.allowedOrigins||[]),b.botProtection===false?0:1,b.honeypotField||null,1,t,t,JSON.stringify(b.metadata||{})).run(); return ok({id:iid,slug,publicUrl:`${env.PUBLIC_ORIGIN}/${path}`},201)} if(parts[2]==='submissions'){const intake=await env.DB.prepare('SELECT * FROM intakes WHERE (id=? OR slug=?) AND tenant_id=?').bind(parts[1],parts[1],a.tenant.id).first<any>(); if(!intake)return err('not_found','Intake not found.',404); const rs=await env.DB.prepare('SELECT id,timestamp_utc,payload_json,origin,referrer_host,country,request_id FROM intake_submissions WHERE intake_id=? ORDER BY timestamp_utc DESC LIMIT 200').bind(intake.id).all<any>(); return ok({items:rs.results.map((r:any)=>({...r,payload:parseJson(r.payload_json,{})}))})} if(method==='GET'&&!parts[1]){const rs=await env.DB.prepare('SELECT * FROM intakes WHERE tenant_id=? ORDER BY updated_utc DESC LIMIT 100').bind(a.tenant.id).all(); return ok({items:rs.results})}}
 if(parts[0]==='analytics'){const a=await auth(req,env,'analytics:read'); if(a instanceof Response)return a; if(parts[1]==='summary'){const rs=await env.DB.prepare('SELECT decision,count(*) count FROM alias_events GROUP BY decision').all(); return ok({summary:rs.results})} if(parts[1]==='links'){const link=await env.DB.prepare('SELECT id FROM aliases WHERE id=? AND api_tenant_id=?').bind(parts[2],a.tenant.id).first(); if(!link)return err('not_found','Link not found.',404); const rs=await env.DB.prepare('SELECT decision,count(*) count FROM alias_events WHERE alias_id=? GROUP BY decision').bind(parts[2]).all(); return ok({resourceId:parts[2],summary:rs.results})}}
 if(parts[0]==='nodevertex'){const a=await auth(req,env,parts[1]?.includes('intake')?'intakes:create':'links:create'); if(a instanceof Response)return a; if(a.tenant.slug!=='nodevertex'&&!a.scopes.includes('admin'))return err('forbidden','Node Vertex integration requires nodevertex tenant key.',403); if(parts[1]==='app-links'&&method==='POST'){return apiV1(new Request(req.url.replace('/api/v1/nodevertex/app-links','/api/v1/links'),req),env,['links'],start)} if(parts[1]==='intakes'&&method==='POST'){return apiV1(new Request(req.url.replace('/api/v1/nodevertex/intakes','/api/v1/intakes'),req),env,['intakes'],start)}}
