function linkOut(a:Alias){return {id:a.id,code:a.slug,shortUrl:a.canonical_short_url,destinationUrl:a.target_url,enabled:!!a.is_active,expiresUtc:a.expires_utc,maxClicks:a.max_views,clicks:a.view_count,tags:parseJson(a.tags,[]),notes:a.notes}}
async function publicIntake(req:Request,env:Env,tenantSlug:string,slug:string,start:number){if(req.method!=='POST')return err('method_not_allowed','Only POST is allowed.',405); const intake=await env.DB.prepare('SELECT i.*,t.slug tenant_slug FROM intakes i JOIN tenants t ON t.id=i.tenant_id WHERE t.slug=? AND i.slug=? AND i.is_active=1').bind(tenantSlug,slug).first<any>(); if(!intake)return err('not_found','Intake not found.',404); const ct=req.headers.get('content-type')||''; const payload=ct.includes('json')?await req.json<any>():Object.fromEntries(await req.formData()); if(intake.honeypot_field&&payload[intake.honeypot_field])return ok({accepted:true}); const origin=req.headers.get('origin')||''; const allowed=arr(intake.allowed_origins); if(allowed.length&&origin&&!allowed.includes(origin))return err('forbidden','Origin denied.',403); const ua=req.headers.get('user-agent')||'', ip=req.headers.get('cf-connecting-ip')||'', rid=req.headers.get('cf-ray')||id('req'); await env.DB.prepare('INSERT INTO intake_submissions(id,intake_id,tenant_id,timestamp_utc,payload_json,payload_hash,ip_hash,user_agent_hash,user_agent_summary,origin,referrer_host,country,request_id) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?)').bind(id('sub'),intake.id,intake.tenant_id,now(),JSON.stringify(payload),await sha(JSON.stringify(payload)),ip?await sha(ip):'',ua?await sha(ua):'',uaClass(ua),origin,host(req.headers.get('referer')),req.cf?.country||'',rid).run(); await event(env,req,intake.id,'intake.submit','accepted',202,'accepted',start,intake.tenant_id); return ok({accepted:true,requestId:rid},202)}
async function publicRoute(req:Request,env:Env,path:string,start:number){const r=await env.DB.prepare('SELECT * FROM routes WHERE public_path=? AND is_active=1').bind(path).first<any>(); if(!r)return null; const methods=arr(r.allowed_methods); if(methods.length&&!methods.includes(req.method))return err('method_not_allowed','Method not allowed.',405); await event(env,req,r.id,'route.call','allowed',200,'route',start,r.tenant_id); if(r.type==='redirect')return Response.redirect(r.target_url,302); if(r.type==='proxy'&&r.target_url)return fetch(r.target_url,new Request(req)); if(r.type==='static-response')return new Response(r.static_body||'',{status:r.static_status,headers:{'content-type':'text/plain; charset=utf-8'}}); return ok({route:r.id,type:r.type})}
function page(body:string,title='1db.io'){return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${title}</title><style>${css()}</style></head><body>${body}</body></html>`}
